export function updateShops(G) {
  const p = G.player;
  G.shop = null;
  for (const s of SHOP_DEFS) {
    if (s.id === 'garage' && p.onFoot) continue;
    if (Math.hypot(p.x - s.x, p.z - s.z) < s.r) {
      G.shop = s;
      return;
    }
  }
