      ctx.lineWidth = 6;
      ctx.fillStyle = '#ffffff';
      if (vertical) {
        ctx.font = '900 54px Arial, sans-serif';
        ctx.save();
        ctx.translate(64, 256);
        ctx.rotate(-Math.PI / 2);
        ctx.strokeText(text, 0, 0);
        ctx.shadowBlur = 12;
        ctx.fillText(text, 0, 0);
        ctx.restore();
      } else {
        const size = text.length > 9 ? 46 : 58;
